// Compares the freshly fetched security findings/policy snapshot against the
// last known version stored in workflow static data (per AWS account). No external DB needed.
const cfg = $('Set AWS Configurations').first().json;
const response = $input.first().json;
const newFindingsText = JSON.stringify(response.findings || response.results || response);

const staticData = $getWorkflowStaticData('node');
if (!staticData.findingsByAccount) staticData.findingsByAccount = {};

const previous = staticData.findingsByAccount[cfg.awsAccountId];
const previousFindingsText = previous ? previous.findingsText : null;
const findingsChanged = previousFindingsText !== null && previousFindingsText !== newFindingsText;
const isFirstSeen = previousFindingsText === null;

return [{
  json: {
    ...cfg,
    newFindingsText,
    previousFindingsText: previousFindingsText || '',
    findingsChanged: findingsChanged || isFirstSeen,
    isFirstSeen,
    checkedAt: new Date().toISOString()
  }
}];

const findingsState = $('Check Findings Change').first().json;
const assetData = $input.first().json;

return [{
  json: {
    ...findingsState,
    affectedResources: assetData.resources || assetData.affectedResources || [],
    affectedIamRoles: assetData.iamRoles || assetData.affectedIamRoles || [],
    accountEnvironment: assetData.environment || assetData.env || '',
    vpcNetworks: assetData.vpcs || assetData.networks || []
  }
}];

